package org.apache.commons.cli;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.lang.reflect.Field;
import java.lang.reflect.Method;

import static org.junit.jupiter.api.Assertions.*;

public class OptionBuilder_WithValueSeparator_Test {

    private Method resetMethod;
    private Field valueSeparatorField;
    private Field instanceField;

    @BeforeEach
    public void setUp() throws Exception {
        // Prepare reflective access to private members
        resetMethod = OptionBuilder.class.getDeclaredMethod("reset");
        resetMethod.setAccessible(true);

        valueSeparatorField = OptionBuilder.class.getDeclaredField("valueSeparator");
        valueSeparatorField.setAccessible(true);

        instanceField = OptionBuilder.class.getDeclaredField("INSTANCE");
        instanceField.setAccessible(true);

        // Ensure a clean state before each test
        resetMethod.invoke(null);
    }

    @AfterEach
    public void tearDown() throws Exception {
        // Restore state after each test
        if (resetMethod != null) {
            resetMethod.invoke(null);
        }
    }

    @Test
    public void testWithValueSeparatorSetsValueAndReturnsSingleton() throws Exception {
        // Call withValueSeparator and capture return
        OptionBuilder returned = OptionBuilder.withValueSeparator('|');

        // Ensure returned is not null
        assertNotNull(returned, "withValueSeparator should not return null");

        // Ensure returned is the INSTANCE singleton
        Object instance = instanceField.get(null);
        assertSame(instance, returned, "withValueSeparator should return the singleton INSTANCE");

        // Ensure the private static valueSeparator field equals the provided value
        char stored = valueSeparatorField.getChar(null);
        assertEquals('|', stored, "valueSeparator should be set to the provided character");
    }

    @Test
    public void testWithValueSeparatorOverwritesPreviousValue() throws Exception {
        // Set to one value
        OptionBuilder.withValueSeparator(';');
        assertEquals(';', valueSeparatorField.getChar(null), "Initial valueSeparator should be ';'");

        // Overwrite with another value
        OptionBuilder.withValueSeparator(':');
        assertEquals(':', valueSeparatorField.getChar(null), "valueSeparator should be updated to ':'");

        // Overwrite with the same value again (idempotence check)
        OptionBuilder.withValueSeparator(':');
        assertEquals(':', valueSeparatorField.getChar(null), "valueSeparator should remain ':' after setting same value");
    }

    @Test
    public void testWithValueSeparatorAcceptsNullCharacter() throws Exception {
        // Use the NUL character
        OptionBuilder.withValueSeparator('\0');
        assertEquals('\0', valueSeparatorField.getChar(null), "valueSeparator should be set to NUL character");
    }

    @Test
    public void testMultipleCallsReturnSameInstance() throws Exception {
        OptionBuilder first = OptionBuilder.withValueSeparator('a');
        OptionBuilder second = OptionBuilder.withValueSeparator('b');
        OptionBuilder third = OptionBuilder.withValueSeparator('c');

        Object instance = instanceField.get(null);
        assertSame(instance, first, "first return should be the singleton INSTANCE");
        assertSame(instance, second, "second return should be the singleton INSTANCE");
        assertSame(instance, third, "third return should be the singleton INSTANCE");

        // Confirm last call updated the separator
        assertEquals('c', valueSeparatorField.getChar(null), "valueSeparator should reflect the last set value");
    }
}

